describe('Login Form Keyboard Navigation', () => {
  beforeEach(() => {
    cy.visit('/login');
  });

  it('should navigate through login form fields using Tab key', () => {
    // Focus on username field
    cy.get('input[name="username"]').should('exist');
    cy.get('input[name="username"]').focus();
    cy.get('input[name="username"]').should('have.focus');

    // Tab to password field
    cy.get('input[name="username"]').tab();
    cy.get('input[name="password"]').should('have.focus');

    // Tab to login button
    cy.get('input[name="password"]').tab();
    cy.get('button[type="submit"]').should('have.focus');

    // Tab to remember me checkbox if present
    cy.get('button[type="submit"]').tab();
    cy.get('input[name="rememberMe"]').should('have.focus');
  });

  it('should submit form using keyboard Enter key', () => {
    cy.get('input[name="username"]').type('testuser');
    cy.get('input[name="password"]').type('password123');
    cy.get('input[name="password"]').type('{enter}');

    cy.url().should('not.include', '/login');
    cy.get('[data-testid="dashboard"]').should('be.visible');
  });

  it('should navigate backwards through form fields using Shift+Tab', () => {
    cy.get('button[type="submit"]').focus();
    cy.get('button[type="submit"]').should('have.focus');

    // Shift+Tab to password field
    cy.get('button[type="submit"]').tab({ shift: true });
    cy.get('input[name="password"]').should('have.focus');

    // Shift+Tab to username field
    cy.get('input[name="password"]').tab({ shift: true });
    cy.get('input[name="username"]').should('have.focus');
  });

  it('should maintain focus visibility with keyboard navigation', () => {
    cy.get('input[name="username"]').focus();
    cy.get('input[name="username"]').should('have.css', 'outline').and('not.equal', 'none');

    cy.get('input[name="username"]').tab();
    cy.get('input[name="password"]').should('have.css', 'outline').and('not.equal', 'none');
  });

  it('should allow typing in focused input fields without mouse interaction', () => {
    cy.get('input[name="username"]').focus();
    cy.focused().type('keyboarduser');
    cy.get('input[name="username"]').should('have.value', 'keyboarduser');

    cy.get('input[name="username"]').tab();
    cy.focused().type('securepass123');
    cy.get('input[name="password"]').should('have.value', 'securepass123');
  });

  it('should handle form submission with keyboard when all required fields are filled', () => {
    cy.get('input[name="username"]').focus().type('validuser');
    cy.get('input[name="password"]').focus().type('validpass');
    cy.get('button[type="submit"]').focus().type('{enter}');

    cy.get('[data-testid="success-message"]').should('be.visible');
  });

  it('should show validation errors when submitting empty form via keyboard', () => {
    cy.get('button[type="submit"]').focus().type('{enter}');

    cy.get('[data-testid="username-error"]').should('be.visible').and('contain', 'Username is required');
    cy.get('[data-testid="password-error"]').should('be.visible').and('contain', 'Password is required');
  });

  it('should trap focus within login form modal if present', () => {
    cy.get('[data-testid="login-modal"]').should('be.visible');
    cy.get('input[name="username"]').focus();

    // Tab through all focusable elements
    for (let i = 0; i < 5; i++) {
      cy.focused().tab();
    }

    // Should cycle back to first focusable element
    cy.get('input[name="username"]').should('have.focus');
  });
});
